ost_url($featured)) ?>"><?= mg_e((string)$featured['title']) ?></a></h2><p><?= mg_e((string)$featured['excerpt']) ?></p><div class="mg-blog-meta"><span><?= mg_e(mg_blog_author_name($featured)) ?></span><span><?= mg_e(mg_blog_format_date($featured['published_at']??null)) ?></span><span><?= mg_blog_reading_time((string)$featured['body']) ?> min read</span></div></div></article></section><?php endif; ?><section class="mg-blog-wrap mg-blog-layout"><div><div class="mg-blog-section-head"><div><span class="mg-blog-eyebrow">Latest articles</span><h2><?= $search!==''?'Search results':'Fresh Microgifter thinking' ?></h2></div><?php if($search!==''): ?><a href="/blog.php">Clear search</a><?php endif; ?></div><?php if(!$posts): ?><?php if($search===''&&$totalPosts===0): ?><section class="mg-blog-coming-soon"><span class="mg-blog-eyebrow">Insights coming soon</span><h3><?= mg_e($settings['coming_soon_title']) ?></h3><p><?= mg_e($settings['coming_soon_message']) ?></p><div><a href="/learn-more.php">Book a demo</a><a href="/investors.php">Investor page</a></div></section><?php else: ?><div class="mg-blog-empty-panel"><h3>No articles found.</h3><p>Try a different search or check back soon for new Microgifter updates.</p></div><?php endif; ?><?php else: ?><div class="mg-blog-grid"><?php foreach($posts as $post): ?><article class="mg-blog-card"><a class="mg-blog-card-media" href="<?= mg_e(mg_blog_public_post_url($post)) ?>" style="<?= !empty($post['featured_image'])?'background-image:url('.mg_e((string)$post['featured_image']).')':'' ?>"></a><div class="mg-blog-card-body"><div class="mg-blog-card-top"><?php if(!empty($post['category_name'])): ?><a href="<?= mg_e(mg_blog_public_category_url(['slug'=>(string)$post['category_slug']])) ?>"><?= mg_e((string)$post['category_name']) ?></a><?php endif; ?><span><?= mg_e(mg_blog_format_date($post['published_at']??null)) ?></span></div><h3><a href="<?= mg_e(mg_blog_public_post_url($post)) ?>"><?= mg_e((string)$post['title']) ?></a></h3><p><?= m